import numpy as np
def comps_of(g,bg=None):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if bg is None or g[i][j]!=bg and not seen[i][j]:
                v=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and (bg is None or g[nx][ny]!=bg) and g[nx][ny]==v and not seen[nx][ny]:
                            seen[nx][ny]=True; st.append((nx,ny))
                rs=[r for r,c in cells]; cc=[c for r,c in cells]
                sh=tuple(sorted((r-min(rs),c-min(cc)) for r,c in cells))
                res.append((v,cells,sh,(min(rs),max(rs),min(cc),max(cc))))
    return res
