import numpy as np
def comps(g,bg=None):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                v=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==v and not seen[nx][ny]:
                            seen[nx][ny]=True; st.append((nx,ny))
                cells.sort()
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                sh=tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))
                res.append({'v':v,'cells':cells,'sh':sh,'r0':min(rs),'r1':max(rs),'c0':min(cs),'c1':max(cs)})
    return res
