        grp.setdefault(key,[]).append(cells)
    for key,lst in grp.items():
        if len(lst)==2:
            a,b=lst
            def mind(o1,o2):
                best=10**9
                for p in o1:
                    for q in o2:
                        d=max(abs(p[0]-q[0]),abs(p[1]-q[1]))
                        best=min(best,d)
                return best
            d1=mind(a,tgt); d2=mind(b,tgt)
